import re

def parse(lines):
    blocks = []
    skip = []
    n = len(lines)
    i = 0
    while i < n:
        if not lines[i].strip():
            i += 1
            continue
        h = lines[i]
        cols = [(m.start(), m.group()) for m in re.finditer(r'\S+(?: \S+)*', h)]
        idx = [i]
        recs = []
        j = i + 1
        while j < n and lines[j].strip():
            l = lines[j]
            bounds = []
            for k in range(len(cols)):
                if k + 1 < len(cols):
                    e = cols[k + 1][0]
                    if e > len(l):
                        e = len(l)
                    while e > 0 and e < len(l) and l[e - 1] != ' ' and l[e] != ' ':
                        e -= 1
                    bounds.append(e)
            r = {}
            prev = 0
            for k, (s, name) in enumerate(cols):
                start = prev if k > 0 else 0
                if k + 1 < len(cols):
                    end = bounds[k]
                    if end < start:
                        end = start
                    r[name] = l[start:end].strip()
                    prev = end
                else:
                    r[name] = l[start:].strip()
            recs.append(r)
            idx.append(j)
            j += 1
        name = cols[0][1].lower() if cols else 'section'
        if recs:
            blocks.append({'name': name, 'kind': 'table', 'lines': idx, 'records': recs})
        else:
            skip.append(i)
        i = j
    return {'blocks': blocks, 'skip': skip}
